//! Runtime for mechanically lifted functions (generated by scripts/lift.py into p2v/*.rs).
//!
//! The lifted code keeps the 16 general registers, the xmm registers and the flags in Rust locals, the stack
//! frame in a 128 KB window at the oracle's stack addresses, and sends every other memory access and every call
//! through `neutral_world::Env`. Flag semantics follow x86 (and QEMU for undefined flags). Nothing here is
//! specific to one function.

use neutral_world::{CallRet, Env, STK};

/// Size of the dump (rel_to_end 0 is the first byte after it).
pub const CODE_N: u64 = 964659;
/// rsp the oracle starts the function with, plus 8 (the return address sits at RSP0 - 8).
pub const RSP0: u64 = 0x7fff_f000;
/// Stack window held by [`Mem`]: [WIN_LO, WIN_LO + WIN) is exactly the 1 MB the Unicorn stack maps (tools/oracle.py
/// STACK_BASE and STACK_SIZE), so a store through a stack-relative computed address lands where the original's lands.
const WIN_LO: u64 = 0x7ff0_0000;
const WIN: usize = 0x10_0000;
/// Unicorn (no paging) drops address bits 52..63 of every data access (measured with hand-written probes in
/// scripts/uc_addr_probe2.py: bits 0..51 are kept, a set bit 52 or above is ignored, the memory hook sees the masked
/// address). Real hardware would raise #GP for such non-canonical addresses; the port follows the measured emulator.
pub const ADDR_MASK: u64 = (1u64 << 52) - 1;
/// Addresses the world harness normalises to `STK` in call arguments.
const NORM_LO: u64 = 0x7ff0_0000;
const NORM_HI: u64 = 0x8000_1000;

pub const SAVED_RBX: u64 = 0x1111_1111_1111_1111;
pub const SAVED_RBP: u64 = 0x2222_2222_2222_2222;
pub const SAVED_R12: u64 = 0x3333_3333_3333_3333;
pub const SAVED_R13: u64 = 0x4444_4444_4444_4444;
pub const SAVED_R14: u64 = 0x5555_5555_5555_5555;
pub const SAVED_R15: u64 = 0x6666_6666_6666_6666;

/// Registers a lifted function returns (the spec decides which ones are compared).
#[derive(Debug, Clone, Copy, Default)]
pub struct Ret {
    pub rax: u64,
    pub rdx: u64,
    pub xmm0: u128,
}

impl Ret {
    pub fn from_call(r: CallRet) -> Ret {
        Ret { rax: r.rax, rdx: r.rdx, xmm0: (r.xmm0_lo as u128) | ((r.xmm0_hi as u128) << 64) }
    }
}

thread_local! {
    static ALLOCS: std::cell::RefCell<Vec<u64>> = std::cell::RefCell::new(Vec::new());
}

/// Stub offsets (rel_to_end) declared as allocators in the spec of the vector set being replayed.
pub fn set_allocs(v: Vec<u64>) {
    ALLOCS.with(|c| *c.borrow_mut() = v);
}

thread_local! {
    static STK_OVR: std::cell::RefCell<Vec<(u64, usize, i64)>> = std::cell::RefCell::new(Vec::new());
}

/// Result overrides (`ovr` header lines of the vector file: target, argument index, delta) that keep a stack address.
pub fn set_stk_ovr(v: Vec<(u64, usize, i64)>) {
    STK_OVR.with(|c| *c.borrow_mut() = v);
}

/// Memory and calls of one lifted run: the stack window plus the world.
pub struct Mem<'a, E: Env> {
    pub env: &'a mut E,
    stk: Vec<u8>,
    alloc_n: u64,
}

#[inline(always)]
fn norm(v: u64) -> u64 {
    if (NORM_LO..NORM_HI).contains(&v) {
        STK
    } else {
        v
    }
}

macro_rules! rd_impl {
    ($name:ident, $envname:ident, $t:ty, $n:expr) => {
        #[inline(always)]
        pub fn $name(&mut self, a: u64) -> $t {
            let a = a & ADDR_MASK;
            if a >= WIN_LO && a + $n <= WIN_LO + WIN as u64 {
                let o = (a - WIN_LO) as usize;
                <$t>::from_le_bytes(self.stk[o..o + $n].try_into().unwrap())
            } else {
                self.env.$envname(a)
            }
        }
    };
}

macro_rules! wr_impl {
    ($name:ident, $envname:ident, $t:ty, $n:expr) => {
        #[inline(always)]
        pub fn $name(&mut self, a: u64, v: $t) {
            let a = a & ADDR_MASK;
            if a >= WIN_LO && a + $n <= WIN_LO + WIN as u64 {
                let o = (a - WIN_LO) as usize;
                self.stk[o..o + $n].copy_from_slice(&v.to_le_bytes());
            } else {
                self.env.$envname(a, v)
            }
        }
    };
}

impl<'a, E: Env> Mem<'a, E> {
    /// `st` are the stack arguments (slot k at RSP0 + 8k).
    pub fn new(env: &'a mut E, st: &[u64]) -> Self {
        let mut m = Mem { env, stk: vec![0u8; WIN], alloc_n: 0 };
        for (k, v) in st.iter().enumerate() {
            m.w64(RSP0 + 8 * k as u64, *v);
        }
        m.w64(RSP0 - 8, 0x0dea_d000);
        m
    }
    rd_impl!(r8, r8, u8, 1);
    rd_impl!(r16, r16, u16, 2);
    rd_impl!(r32, r32, u32, 4);
    rd_impl!(r64, r64, u64, 8);
    rd_impl!(r128, r128, u128, 16);
    wr_impl!(w8, w8, u8, 1);
    wr_impl!(w16, w16, u16, 2);
    wr_impl!(w32, w32, u32, 4);
    wr_impl!(w64, w64, u64, 8);
    wr_impl!(w128, w128, u128, 16);

    /// Call through the world; stack addresses in the arguments become `STK` like in the oracle's trace.
    pub fn call(&mut self, target: u64, iargs: &[u64], fargs: &[u64]) -> CallRet {
        let ia: Vec<u64> = iargs.iter().map(|v| norm(*v)).collect();
        let mut r = self.env.call_f(target, &ia, fargs);
        // allocator stubs declared in the spec ("alloc"): the k-th allocation of a world returns the k-th 64 KB block of the data
        // area at anchor + 0x700000 (scripts/fxpatch.py does the same in the original); an ASSUMPTION about the callee
        ALLOCS.with(|c| {
            for &rel in c.borrow().iter() {
                if target == self.env.data_va(rel as i64) {
                    r.rax = self.env.data_va(0x70_0000 + 0x1_0000 * self.alloc_n as i64);
                    self.alloc_n += 1;
                }
            }
        });
        // stack preserving result overrides (scripts/fxpatch.py): the declared "returns argK + d" gives the real stack
        // address when the argument points into the frame, where the shared harness would hand back STK
        STK_OVR.with(|c| {
            for &(t, ai, d) in c.borrow().iter() {
                if t == target && ai < iargs.len() && norm(iargs[ai]) != iargs[ai] {
                    r.rax = iargs[ai].wrapping_add(d as u64);
                }
            }
        });
        r
    }
}

/// Arithmetic flags (af is not modelled; nothing in the dump depends on it).
#[derive(Debug, Clone, Copy, Default)]
pub struct Fl {
    pub cf: bool,
    pub zf: bool,
    pub sf: bool,
    pub of: bool,
    pub pf: bool,
}

impl Fl {
    #[inline(always)]
    pub fn e(&self) -> bool { self.zf }
    #[inline(always)]
    pub fn ne(&self) -> bool { !self.zf }
    #[inline(always)]
    pub fn b(&self) -> bool { self.cf }
    #[inline(always)]
    pub fn ae(&self) -> bool { !self.cf }
    #[inline(always)]
    pub fn be(&self) -> bool { self.cf || self.zf }
    #[inline(always)]
    pub fn a(&self) -> bool { !self.cf && !self.zf }
    #[inline(always)]
    pub fn l(&self) -> bool { self.sf != self.of }
    #[inline(always)]
    pub fn ge(&self) -> bool { self.sf == self.of }
    #[inline(always)]
    pub fn le(&self) -> bool { self.zf || self.sf != self.of }
    #[inline(always)]
    pub fn g(&self) -> bool { !self.zf && self.sf == self.of }
    #[inline(always)]
    pub fn s(&self) -> bool { self.sf }
    #[inline(always)]
    pub fn ns(&self) -> bool { !self.sf }
    #[inline(always)]
    pub fn o(&self) -> bool { self.of }
    #[inline(always)]
    pub fn no(&self) -> bool { !self.of }
    #[inline(always)]
    pub fn p(&self) -> bool { self.pf }
    #[inline(always)]
    pub fn np(&self) -> bool { !self.pf }
}

#[inline(always)]
pub fn mask<const W: u32>() -> u64 {
    if W == 64 {
        u64::MAX
    } else {
        (1u64 << W) - 1
    }
}

#[inline(always)]
fn sign<const W: u32>(v: u64) -> bool {
    (v >> (W - 1)) & 1 != 0
}

#[inline(always)]
fn par(r: u64) -> bool {
    (r as u8).count_ones() % 2 == 0
}

#[inline(always)]
fn zsp<const W: u32>(r: u64) -> (bool, bool, bool) {
    (r == 0, sign::<W>(r), par(r))
}

/// Sign-extends the W-bit value to i64.
#[inline(always)]
pub fn sx<const W: u32>(v: u64) -> i64 {
    let sh = 64 - W;
    ((v << sh) as i64) >> sh
}

pub fn add<const W: u32>(a: u64, b: u64) -> (u64, Fl) {
    let m = mask::<W>();
    let (a, b) = (a & m, b & m);
    let r = a.wrapping_add(b) & m;
    let (zf, sf, pf) = zsp::<W>(r);
    (r, Fl { cf: r < a, zf, sf, of: sign::<W>((a ^ r) & (b ^ r)), pf })
}

pub fn adc<const W: u32>(a: u64, b: u64, c: bool) -> (u64, Fl) {
    let m = mask::<W>();
    let (a, b) = (a & m, b & m);
    let r = a.wrapping_add(b).wrapping_add(c as u64) & m;
    let (zf, sf, pf) = zsp::<W>(r);
    let cf = (a as u128 + b as u128 + c as u128) > m as u128;
    (r, Fl { cf, zf, sf, of: sign::<W>((a ^ r) & (b ^ r)), pf })
}

pub fn sub<const W: u32>(a: u64, b: u64) -> (u64, Fl) {
    let m = mask::<W>();
    let (a, b) = (a & m, b & m);
    let r = a.wrapping_sub(b) & m;
    let (zf, sf, pf) = zsp::<W>(r);
    (r, Fl { cf: a < b, zf, sf, of: sign::<W>((a ^ b) & (a ^ r)), pf })
}

pub fn sbb<const W: u32>(a: u64, b: u64, c: bool) -> (u64, Fl) {
    let m = mask::<W>();
    let (a, b) = (a & m, b & m);
    let r = a.wrapping_sub(b).wrapping_sub(c as u64) & m;
    let (zf, sf, pf) = zsp::<W>(r);
    let cf = (a as u128) < (b as u128 + c as u128);
    (r, Fl { cf, zf, sf, of: sign::<W>((a ^ b) & (a ^ r)), pf })
}

/// Flags of a logic result (and, or, xor, test).
pub fn logic<const W: u32>(r: u64) -> Fl {
    let r = r & mask::<W>();
    let (zf, sf, pf) = zsp::<W>(r);
    Fl { cf: false, zf, sf, of: false, pf }
}

pub fn inc<const W: u32>(a: u64, f: Fl) -> (u64, Fl) {
    let (r, mut n) = add::<W>(a, 1);
    n.cf = f.cf;
    (r, n)
}

pub fn dec<const W: u32>(a: u64, f: Fl) -> (u64, Fl) {
    let (r, mut n) = sub::<W>(a, 1);
    n.cf = f.cf;
    (r, n)
}

pub fn neg<const W: u32>(a: u64) -> (u64, Fl) {
    let (r, mut n) = sub::<W>(0, a);
    n.cf = a & mask::<W>() != 0;
    (r, n)
}

#[inline(always)]
fn cnt_mask<const W: u32>(c: u64) -> u32 {
    (c & if W == 64 { 63 } else { 31 }) as u32
}

pub fn shl<const W: u32>(a: u64, c: u64, f: Fl) -> (u64, Fl) {
    let n = cnt_mask::<W>(c);
    if n == 0 {
        return (a & mask::<W>(), f);
    }
    let m = mask::<W>();
    let a = a & m;
    let r = if n >= 64 { 0 } else { (a << n) & m };
    let cf = if n <= W { (a >> (W - n)) & 1 != 0 } else { false };
    let (zf, sf, pf) = zsp::<W>(r);
    (r, Fl { cf, zf, sf, of: sign::<W>(r) != cf, pf })
}

pub fn shr<const W: u32>(a: u64, c: u64, f: Fl) -> (u64, Fl) {
    let n = cnt_mask::<W>(c);
    if n == 0 {
        return (a & mask::<W>(), f);
    }
    let m = mask::<W>();
    let a = a & m;
    let r = if n >= 64 { 0 } else { a >> n };
    let cf = if n <= W { (a >> (n - 1)) & 1 != 0 } else { false };
    let (zf, sf, pf) = zsp::<W>(r);
    (r, Fl { cf, zf, sf, of: sign::<W>(a), pf })
}

pub fn sar<const W: u32>(a: u64, c: u64, f: Fl) -> (u64, Fl) {
    let n = cnt_mask::<W>(c);
    if n == 0 {
        return (a & mask::<W>(), f);
    }
    let v = sx::<W>(a);
    let r = ((v >> n.min(63)) as u64) & mask::<W>();
    let cf = ((v >> (n - 1).min(63)) & 1) != 0;
    let (zf, sf, pf) = zsp::<W>(r);
    (r, Fl { cf, zf, sf, of: false, pf })
}

pub fn rol<const W: u32>(a: u64, c: u64, f: Fl) -> (u64, Fl) {
    let n = cnt_mask::<W>(c);
    if n == 0 {
        return (a & mask::<W>(), f);
    }
    let m = mask::<W>();
    let a = a & m;
    let k = n % W;
    let r = if k == 0 { a } else { ((a << k) | (a >> (W - k))) & m };
    let cf = r & 1 != 0;
    (r, Fl { cf, of: sign::<W>(r) != cf, ..f })
}

pub fn ror<const W: u32>(a: u64, c: u64, f: Fl) -> (u64, Fl) {
    let n = cnt_mask::<W>(c);
    if n == 0 {
        return (a & mask::<W>(), f);
    }
    let m = mask::<W>();
    let a = a & m;
    let k = n % W;
    let r = if k == 0 { a } else { ((a >> k) | (a << (W - k))) & m };
    let cf = sign::<W>(r);
    let of = (((r >> (W - 1)) ^ (r >> (W - 2))) & 1) != 0;
    (r, Fl { cf, of, ..f })
}

/// Two/three operand imul: the low W bits of the signed product; cf = of = the product does not fit.
pub fn imul<const W: u32>(a: u64, b: u64) -> (u64, Fl) {
    let p = (sx::<W>(a) as i128) * (sx::<W>(b) as i128);
    let r = (p as u64) & mask::<W>();
    let over = p != sx::<W>(r) as i128;
    let (zf, sf, pf) = zsp::<W>(r);
    (r, Fl { cf: over, zf, sf, of: over, pf })
}

/// One operand mul: returns (low, high, flags) of the unsigned W x W bit product.
pub fn mul1<const W: u32>(a: u64, b: u64) -> (u64, u64, Fl) {
    let m = mask::<W>();
    let p = (a & m) as u128 * (b & m) as u128;
    let lo = (p as u64) & m;
    let hi = ((p >> W) as u64) & m;
    let over = hi != 0;
    let (zf, sf, pf) = zsp::<W>(lo);
    (lo, hi, Fl { cf: over, zf, sf, of: over, pf })
}

/// One operand imul: returns (low, high, flags) of the signed product.
pub fn imul1<const W: u32>(a: u64, b: u64) -> (u64, u64, Fl) {
    let m = mask::<W>();
    let p = (sx::<W>(a) as i128) * (sx::<W>(b) as i128);
    let lo = (p as u64) & m;
    let hi = ((p >> W) as u64) & m;
    let over = p != sx::<W>(lo) as i128;
    let (zf, sf, pf) = zsp::<W>(lo);
    (lo, hi, Fl { cf: over, zf, sf, of: over, pf })
}

/// Unsigned divide of (hi:lo) by d; panics on d == 0 or quotient overflow (the original faults, the case is skipped).
pub fn div<const W: u32>(hi: u64, lo: u64, d: u64) -> (u64, u64) {
    let m = mask::<W>();
    let d = (d & m) as u128;
    assert!(d != 0, "divide by zero");
    let n = (((hi & m) as u128) << W) | (lo & m) as u128;
    let q = n / d;
    assert!(q <= m as u128, "divide overflow");
    (q as u64, (n % d) as u64)
}

pub fn idiv<const W: u32>(hi: u64, lo: u64, d: u64) -> (u64, u64) {
    let m = mask::<W>();
    assert!((d & m) != 0, "divide by zero");
    let n: i128 = ((((hi & m) as u128) << W) | (lo & m) as u128) as i128;
    let n = if W == 64 { n } else { (n << (128 - 2 * W)) >> (128 - 2 * W) };
    let dv = sx::<W>(d) as i128;
    let q = n / dv;
    let r = n % dv;
    let lim = 1i128 << (W - 1);
    assert!(q >= -lim && q < lim, "divide overflow");
    ((q as u64) & m, (r as u64) & m)
}

/// bt/bts/btr/btc with a register or immediate bit offset: returns the selected bit.
#[inline(always)]
pub fn bit<const W: u32>(a: u64, off: u64) -> bool {
    (a >> (off & (W as u64 - 1))) & 1 != 0
}

pub fn bsf<const W: u32>(a: u64) -> Option<u64> {
    let a = a & mask::<W>();
    if a == 0 {
        None
    } else {
        Some(a.trailing_zeros() as u64)
    }
}

pub fn bsr<const W: u32>(a: u64) -> Option<u64> {
    let a = a & mask::<W>();
    if a == 0 {
        None
    } else {
        Some(63 - a.leading_zeros() as u64)
    }
}

// ---- floating point -------------------------------------------------------------------------------------------

#[inline(always)]
pub fn lo64(x: u128) -> u64 {
    x as u64
}

#[inline(always)]
pub fn set_lo64(x: u128, v: u64) -> u128 {
    (x & !(u64::MAX as u128)) | v as u128
}

#[inline(always)]
pub fn set_lo32(x: u128, v: u32) -> u128 {
    (x & !(u32::MAX as u128)) | v as u128
}

#[inline(always)]
pub fn f64_of(x: u128) -> f64 {
    f64::from_bits(x as u64)
}

#[inline(always)]
pub fn f32_of(x: u128) -> f32 {
    f32::from_bits(x as u32)
}

/// comisd/ucomisd/comiss/ucomiss flags.
pub fn ucomi(a: f64, b: f64) -> Fl {
    if a.is_nan() || b.is_nan() {
        Fl { cf: true, zf: true, pf: true, sf: false, of: false }
    } else if a > b {
        Fl::default()
    } else if a < b {
        Fl { cf: true, ..Fl::default() }
    } else {
        Fl { zf: true, ..Fl::default() }
    }
}

/// cvttsd2si / cvttss2si to 32 bits.
pub fn cvtt32(v: f64) -> u32 {
    if v.is_nan() || v >= 2147483648.0 || v <= -2147483649.0 {
        0x8000_0000
    } else {
        (v as i32) as u32
    }
}

pub fn cvtt64(v: f64) -> u64 {
    if v.is_nan() || v >= 9223372036854775808.0 || v < -9223372036854775808.0 {
        0x8000_0000_0000_0000
    } else {
        (v as i64) as u64
    }
}

/// maxsd/minsd style select: `a < b ? a : b` semantics are written out by the generator; helpers for cvtsd2si.
pub fn cvt_round32(v: f64) -> u32 {
    let r = v.round_ties_even();
    if v.is_nan() || r >= 2147483648.0 || r < -2147483648.0 {
        0x8000_0000
    } else {
        (r as i32) as u32
    }
}

pub fn cvt_round64(v: f64) -> u64 {
    let r = v.round_ties_even();
    if v.is_nan() || r >= 9223372036854775808.0 || r < -9223372036854775808.0 {
        0x8000_0000_0000_0000
    } else {
        (r as i64) as u64
    }
}

/// Value the lifted code leaves in registers an opaque call clobbered (the world harness randomises them).
pub const POISON: u64 = 0xdead_beef_dead_beef;

impl Ret {
    /// A lifted function's result as the result of a call (used for self recursion that the original executes natively).
    pub fn as_call(self) -> CallRet {
        CallRet { rax: self.rax, rdx: self.rdx, xmm0_lo: self.xmm0 as u64, xmm0_hi: (self.xmm0 >> 64) as u64 }
    }
}

// ---- SSE2 packed integer and shuffle helpers (fleet-8) ------------------------------------------------------------

#[inline(always)]
fn dw(x: u128, i: u32) -> u32 {
    (x >> (32 * i)) as u32
}

#[inline(always)]
fn from_dw(a: [u32; 4]) -> u128 {
    (a[0] as u128) | ((a[1] as u128) << 32) | ((a[2] as u128) << 64) | ((a[3] as u128) << 96)
}

/// pshufd dst, src, imm8: dword i of the result is dword `(imm >> 2i) & 3` of the source.
pub fn pshufd(src: u128, imm: u8) -> u128 {
    from_dw([
        dw(src, (imm & 3) as u32),
        dw(src, ((imm >> 2) & 3) as u32),
        dw(src, ((imm >> 4) & 3) as u32),
        dw(src, ((imm >> 6) & 3) as u32),
    ])
}

/// shufps dst, src, imm8: the two low result dwords come from dst, the two high ones from src.
pub fn shufps(dst: u128, src: u128, imm: u8) -> u128 {
    from_dw([
        dw(dst, (imm & 3) as u32),
        dw(dst, ((imm >> 2) & 3) as u32),
        dw(src, ((imm >> 4) & 3) as u32),
        dw(src, ((imm >> 6) & 3) as u32),
    ])
}

/// pinsrw xmm, r32/m16, imm8: replaces word `imm & 7` with the low 16 bits of `v`.
pub fn pinsrw(dst: u128, v: u64, imm: u8) -> u128 {
    let sh = 16 * (imm & 7) as u32;
    (dst & !(0xffffu128 << sh)) | (((v & 0xffff) as u128) << sh)
}

/// pmuludq: qword 0 = dword0 * dword0, qword 1 = dword2 * dword2 (unsigned 32 x 32 -> 64).
pub fn pmuludq(a: u128, b: u128) -> u128 {
    let lo = (dw(a, 0) as u64) * (dw(b, 0) as u64);
    let hi = (dw(a, 2) as u64) * (dw(b, 2) as u64);
    (lo as u128) | ((hi as u128) << 64)
}

/// paddd: four wrapping dword additions.
pub fn paddd(a: u128, b: u128) -> u128 {
    from_dw([
        dw(a, 0).wrapping_add(dw(b, 0)),
        dw(a, 1).wrapping_add(dw(b, 1)),
        dw(a, 2).wrapping_add(dw(b, 2)),
        dw(a, 3).wrapping_add(dw(b, 3)),
    ])
}

/// pslld by `cnt` (an 8 bit immediate or the low qword of an xmm/m128 count): every count above 31 gives zero.
pub fn pslld(a: u128, cnt: u64) -> u128 {
    if cnt > 31 {
        return 0;
    }
    from_dw([dw(a, 0) << cnt, dw(a, 1) << cnt, dw(a, 2) << cnt, dw(a, 3) << cnt])
}

/// psrld by `cnt`: every count above 31 gives zero.
pub fn psrld(a: u128, cnt: u64) -> u128 {
    if cnt > 31 {
        return 0;
    }
    from_dw([dw(a, 0) >> cnt, dw(a, 1) >> cnt, dw(a, 2) >> cnt, dw(a, 3) >> cnt])
}

/// psrad by `cnt`: counts above 31 behave like 31 (every lane becomes its sign).
pub fn psrad(a: u128, cnt: u64) -> u128 {
    let c = if cnt > 31 { 31 } else { cnt as u32 };
    from_dw([
        ((dw(a, 0) as i32) >> c) as u32,
        ((dw(a, 1) as i32) >> c) as u32,
        ((dw(a, 2) as i32) >> c) as u32,
        ((dw(a, 3) as i32) >> c) as u32,
    ])
}

/// haddpd dst, src: result.lo = dst.lo + dst.hi, result.hi = src.lo + src.hi (f64 additions).
pub fn haddpd(dst: u128, src: u128) -> u128 {
    let f = |x: u64| f64::from_bits(x);
    let lo = f(dst as u64) + f((dst >> 64) as u64);
    let hi = f(src as u64) + f((src >> 64) as u64);
    (lo.to_bits() as u128) | ((hi.to_bits() as u128) << 64)
}

#[cfg(test)]
mod simd_tests {
    use super::*;

    const V: u128 = 0x4444_4444_3333_3333_2222_2222_1111_1111;

    #[test]
    fn pshufd_cases() {
        // imm 0x1b = 00_01_10_11: reverse the dwords
        assert_eq!(pshufd(V, 0x1b), 0x1111_1111_2222_2222_3333_3333_4444_4444);
        // imm 0xf5 = 11_11_01_01: [d1, d1, d3, d3]
        assert_eq!(pshufd(V, 0xf5), 0x4444_4444_4444_4444_2222_2222_2222_2222);
        // imm 0: broadcast dword 0
        assert_eq!(pshufd(V, 0), 0x1111_1111_1111_1111_1111_1111_1111_1111);
        // imm 0xe4 = identity
        assert_eq!(pshufd(V, 0xe4), V);
    }

    #[test]
    fn shufps_cases() {
        let a: u128 = 0x0a3_u128 << 96 | 0x0a2_u128 << 64 | 0x0a1_u128 << 32 | 0x0a0;
        let b: u128 = 0x0b3_u128 << 96 | 0x0b2_u128 << 64 | 0x0b1_u128 << 32 | 0x0b0;
        // 0x88 = 10_00_10_00: [a0, a2, b0, b2]
        assert_eq!(shufps(a, b, 0x88), 0x0b2_u128 << 96 | 0x0b0_u128 << 64 | 0x0a2_u128 << 32 | 0x0a0);
        // 0xd8 = 11_01_10_00: [a0, a2, b1, b3]
        assert_eq!(shufps(a, b, 0xd8), 0x0b3_u128 << 96 | 0x0b1_u128 << 64 | 0x0a2_u128 << 32 | 0x0a0);
        // 0xd8 on the same register: [a0, a2, a1, a3]
        assert_eq!(shufps(a, a, 0xd8), 0x0a3_u128 << 96 | 0x0a1_u128 << 64 | 0x0a2_u128 << 32 | 0x0a0);
    }

    #[test]
    fn pinsrw_cases() {
        assert_eq!(pinsrw(u128::MAX, 0x12345, 3), u128::MAX & !(0xffff_u128 << 48) | (0x2345_u128 << 48));
        assert_eq!(pinsrw(0, 0xffff_ffff_ffff_ffab, 0), 0xffab);
        // the word index is taken modulo 8
        assert_eq!(pinsrw(0, 0x1, 9), 0x1_u128 << 16);
        assert_eq!(pinsrw(0, 0x7, 7), 0x7_u128 << 112);
    }

    #[test]
    fn pmuludq_cases() {
        let a: u128 = 0x9999_9999_0000_0002_ffff_ffff_ffff_ffff;
        let b: u128 = 0x8888_8888_0000_0003_ffff_ffff_ffff_ffff;
        // dword0: 0xffffffff^2 = 0xfffffffe_00000001, dword2: 2 * 3 = 6
        assert_eq!(pmuludq(a, b), (6_u128 << 64) | 0xffff_fffe_0000_0001);
    }

    #[test]
    fn paddd_wraps_per_lane() {
        let a: u128 = 0x0000_0001_ffff_ffff_8000_0000_0000_0005;
        let b: u128 = 0x0000_0001_0000_0001_8000_0000_0000_0007;
        assert_eq!(paddd(a, b), 0x0000_0002_0000_0000_0000_0000_0000_000c);
    }

    #[test]
    fn shift_cases() {
        let x: u128 = 0x7f00_00ff_8000_0001_ff00_0000_0000_00ff;
        assert_eq!(pslld(x, 24), 0xff00_0000_0100_0000_0000_0000_ff00_0000);
        assert_eq!(psrld(x, 24), 0x0000_007f_0000_0080_0000_00ff_0000_0000);
        assert_eq!(psrad(x, 24), 0x0000_007f_ffff_ff80_ffff_ffff_0000_0000);
        // counts above 31
        assert_eq!(pslld(x, 32), 0);
        assert_eq!(psrld(x, 255), 0);
        assert_eq!(psrad(x, 32), 0x0000_0000_ffff_ffff_ffff_ffff_0000_0000);
        assert_eq!(psrad(x, 1 << 40), 0x0000_0000_ffff_ffff_ffff_ffff_0000_0000);
        // count 0 is the identity
        assert_eq!(pslld(x, 0), x);
        assert_eq!(psrad(x, 0), x);
    }

    #[test]
    fn haddpd_cases() {
        let a = (1.0f64.to_bits() as u128) | ((2.0f64.to_bits() as u128) << 64);
        let b = (10.0f64.to_bits() as u128) | ((20.0f64.to_bits() as u128) << 64);
        let r = haddpd(a, b);
        assert_eq!(f64::from_bits(r as u64), 3.0);
        assert_eq!(f64::from_bits((r >> 64) as u64), 30.0);
        let s = haddpd(a, a);
        assert_eq!(f64::from_bits(s as u64), 3.0);
        assert_eq!(f64::from_bits((s >> 64) as u64), 3.0);
    }
}

#[cfg(test)]
mod mem_tests {
    use super::*;
    use neutral_world::{parse, World};

    fn world() -> (neutral_world::WorldVec, ()) {
        let text = "world t entry=0x0 n=100 anchor=0x10000064 stub_end=0x10 args=0 rets=0 seed=1 ptrn=6 heap=aligned fetch=byte\ncase 0 ok seed=0x1\nabi ok\nend\n";
        (parse(text).unwrap(), ())
    }

    #[test]
    fn data_addresses_lose_bits_52_to_63_like_the_emulator() {
        let (vf, _) = world();
        let mut w = World::new(&vf.header, &vf.cases[0], None);
        let mut m = Mem::new(&mut w, &[]);
        // rbp + rcx*4 - 0xa0 with rcx = 0x07ff_ffff_ffff_ffff and rbp = 0x7fff_eff0 is 0x2000_0000_7fff_ef4c
        m.w32(0x2000_0000_7fff_ef4c, 0xdead_beef);
        assert_eq!(m.r32(0x7fff_ef4c), 0xdead_beef);
        // bits 0..51 are kept: bit 51 set is a different address that does not alias the stack word
        assert_ne!(0x0008_0000_7fff_ef4c & ADDR_MASK, 0x7fff_ef4c);
    }

    #[test]
    fn stack_window_is_the_whole_one_megabyte() {
        let (vf, _) = world();
        let mut w = World::new(&vf.header, &vf.cases[0], None);
        let mut m = Mem::new(&mut w, &[0x1234, 0x5678]);
        assert_eq!(m.r64(RSP0), 0x1234);
        assert_eq!(m.r64(RSP0 + 8), 0x5678);
        assert_eq!(m.r64(RSP0 - 8), 0x0dea_d000);
        m.w8(0x7ff0_0000, 7);
        m.w8(0x7fff_ffff, 9);
        assert_eq!(m.r8(0x7ff0_0000), 7);
        assert_eq!(m.r8(0x7fff_ffff), 9);
        assert_eq!(m.r8(0x7ff8_1234), 0);
    }
}
